import json
with open('/app/resources/treasury_bulletin_1968_07.json', 'r') as f:
    data = json.load(f)
# Search for UK/Gilts related content
def search_dict(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if isinstance(v, str) and any(x in v.lower() for x in ['gilt', 'uk', 'united kingdom', 'bank rate']):
                print(f'{path}.{k}: {v[:200]}')
            search_dict(v, f'{path}.{k}')
    elif isinstance(d, list):
        for i, item in enumerate(d):
            search_dict(item, f'{path}[{i}]')

search_dict(data)
